      renwu = "npc",
      role1 = 1111000,
      role2 = 1111101,
      role3 = 101201,
      sentence = "Without a word, I held out my left hand. Resigned, he directly pulled up my right hand, took off my wrist guard, and rolled back my sleeve.",
      next = {33}
    },
    [33] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      role1 = 1111000,
      role2 = 1111101,
      role3 = 101201,
      sentence = "Under the flickering candlelight, the gauze wrapped around my forearm was already soaked with blood.",
      next = {34}
    },
    [34] = {
      beijing = 4412,
      dialog = 2,
      idx = 1,
      male = 1,
      music = "12_Sorrow_Short_Ver",
      renming = "Victor",
      renwu = "npc",
      role1 = 1111000,
      role2 = 1111104,
      role3 = 101204,
      sentence = "How long were you planning to keep it hidden?",
