    },
    [35] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      role1 = 1111000,
      role2 = 1111101,
      role3 = 101201,
      sentence = "As he spoke, he had undone my bandage for me and was reapplying the medicine. The icy cold paste was melted by his warm fingertips, and he was covering my arm bit by bit with it.",
      next = {36}
    },
    [36] = {
      beijing = 4412,
      dhead = 1202,
      dialog = 1,
      music = "12_Sorrow_Short_Ver",
      renming = "$u",
      renwu = "npc",
      role1 = 1111000,
      role2 = 1111101,
      role3 = 101201,
      sentence = "...I'm only one step away from taking back the palace and getting revenge for my father. I'll hold this sword steady no matter what.",
