    },
    [37] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      role1 = 1111000,
      role2 = 1111111,
      role3 = 101201,
      sentence = "Victor let out an almost inaudible sigh.",
