      dialog = 2,
      idx = 1,
      male = 1,
      music = "12_Sorrow_Short_Ver",
      renming = "Victor",
      renwu = "npc",
      role1 = 1111000,
      role2 = 1111104,
      role3 = 101201,
      sentence = "The several times you took the dangerous move on the battlefield were all because you had vengeance on your mind.",
