    },
    [42] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "Victor's mother died due to an illness, and worried that Victor would get caught up in bickering over the throne, the former king gifted him a city and conferred the title of King of Rigel upon him, distancing him from Unipolis.",
      next = {43}
    },
    [43] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "Five years ago, Lord Chen took advantage of the former king falling seriously ill to lead a revolt, slaughtering the entire royal bloodline and usurping the throne.",
      next = {44}
    },
    [44] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "Victor's father and brothers were all killed by Lord Chen. He didn't bring it up often, but I knew it was eating him away inside.",
