    [47] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "When Lord Chen stormed Unipolis with troops, my father led a counter-insurgency, but was betrayed by a trusted follower and trapped in a canyon.",
