    },
    [48] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "He wanted me to lead a detachment in the night to Rigel City to request reinforcements — at the time, all loyal soldiers had gathered under the King of Rigel's banner, so Rigel City was a stronghold of the old guard.",
      next = {49}
    },
    [49] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "But Lord Chen was ready and set an ambush along the way. My brothers-in-arms protecting me all met tragic deaths one by one. In the end, I was the only one who broke through the encirclement.",
      next = {50}
    },
    [50] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "It was already night then when I reached the city, and the city gate was locked shut. I was shot with arrows in my back and fell off the horse. Without even the strength to knock on the gate, I passed out outside Rigel City.",
      next = {51}
    },
    [51] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "When I awoke, I was looking at Victor's face. A torch shone in my eyes, reflecting a worried, furrowed brow.",
