    [52] = {
      beijing = 4412,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "Five years had now gone by, but these memories still reappeared in my mind from time to time, as clear as yesterday.",
